// Bounded diagnostic capture, isolated from timed performance measurements.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class CyberOrbFrameEvents {
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/CyberOrb/V3.2");
 static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
 static Type utility,windowType;static EditorWindow window,focused;static bool created,background,paused;static GameObject demo;static bool demoActive;static List<GameObject> clones=new List<GameObject>();static List<object> reports=new List<object>();static int count=1,stage,attempts;static double begin;
 static object Field(object obj,string name)=>obj.GetType().GetField(name,flags)?.GetValue(obj);
 static void Disable(){windowType.GetMethod("DisableFrameDebugger",flags).Invoke(window,null);EditorApplication.isPaused=false;}
 static void Setup(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();for(int i=0;i<count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/CyberOrb/Prefabs/CyberOrb_ProjectileVisual.prefab"));g.name="CyberOrb_FrameProbe_"+i;g.transform.position=new Vector3(0,1.8f,0);clones.Add(g);}stage=0;begin=Time.timeAsDouble;}
 static void Finish(string error=null){EditorApplication.update-=Tick;try{Disable();}catch{}foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);if(demo!=null)demo.SetActive(demoActive);Application.runInBackground=background;EditorApplication.isPaused=paused;if(created&&window!=null)window.Close();if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"FrameDebuggerEvents.json"),JsonConvert.SerializeObject(new{error,method="Official FrameDebuggerWindow capture; 1/8 overlapping real Play Mode Visual instances. Diagnostic only, never timed performance.",reports,limitation="Metadata/representative names alone do not prove all renderer merges. Details are available only when native GetFrameEventData succeeds.",restored=true},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Play Mode stopped");return;}if(stage==0&&Time.timeAsDouble-begin>.8){EditorApplication.isPaused=true;windowType.GetMethod("EnableFrameDebugger",flags).Invoke(window,null);stage=1;begin=EditorApplication.timeSinceStartup;return;}
  if(stage==1&&EditorApplication.timeSinceStartup-begin>.7){var events=(Array)utility.GetMethod("GetFrameEvents",flags).Invoke(null,null);if((events==null||events.Length==0)&&attempts++<2){begin=EditorApplication.timeSinceStartup;return;}var list=new List<object>();int detailAttempts=0;if(events!=null)for(int i=0;i<events.Length;i++){
   var evt=events.GetValue(i);var obj=Field(evt,"m_Obj") as UnityEngine.Object;var type=Field(evt,"m_Type")?.ToString();if(type==null)continue;bool ok=false;object detail=null;
   if(obj!=null&&detailAttempts++<6){try{var dt=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerEventData");var data=Activator.CreateInstance(dt,true);ok=(bool)utility.GetMethod("GetFrameEventData",flags).Invoke(null,new[]{(object)i,data});if(ok)detail=new{shader=Field(data,"m_RealShaderName")?.ToString(),pass=Field(data,"m_PassName")?.ToString(),draws=Field(data,"m_DrawCallCount"),instances=Field(data,"m_InstanceCount"),vertices=Field(data,"m_VertexCount")};}catch{}}
   list.Add(new{index=i,type,obj=obj==null?null:obj.name,info=utility.GetMethod("GetFrameEventInfoName",flags).Invoke(null,new object[]{i})?.ToString(),dataOk=ok,detail});
  }reports.Add(new{instances=count,totalEvents=events?.Length??0,events=list,particles=clones.Sum(g=>g.GetComponentsInChildren<ParticleSystem>().Sum(p=>p.particleCount)),batches=UnityStats.batches,draws=UnityStats.drawCalls,setPass=UnityStats.setPassCalls});Disable();if(count==1){count=8;attempts=0;Setup();}else Finish();}
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets")throw new Exception("Wrong target/state");utility=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerUtility");windowType=typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow");focused=EditorWindow.focusedWindow;background=Application.runInBackground;paused=EditorApplication.isPaused;Application.runInBackground=true;window=Resources.FindObjectsOfTypeAll(windowType).Cast<EditorWindow>().FirstOrDefault();created=window==null;if(created)window=EditorWindow.GetWindow(windowType);demo=GameObject.Find("CyberOrb_Demo");demoActive=demo!=null&&demo.activeSelf;if(demo!=null)demo.SetActive(false);Setup();EditorApplication.update+=Tick;return "Bounded native Frame Debugger capture scheduled.";}
}
